const stack = [
  { fn: (next) => { console.log("1"); next(new Error("boom")); } },
  { fn: (next) => { console.log("2"); next(); } },
  { err: (e, next) => { console.log("error:", e.message); next(); } },
  { fn: (next) => { console.log("3"); next(); } },
];
let i = 0;
const next = (err) => {
  const layer = stack[i++];
  if (!layer) return;
  if (err) layer.err ? layer.err(err, next) : next(err);
  else layer.fn ? layer.fn(next) : next();
};
next();

